-- One bounded J13 test. Additive: existing catalog, pilot limits and admin commands remain intact.
create schema forecast_league;
revoke all on schema forecast_league from public,anon,authenticated,service_role;
create table forecast_league.teams(team text primary key, fixture jsonb not null, source_urls jsonb not null);
create table forecast_league.roster(id text primary key,team text not null references forecast_league.teams(team),name text not null);
create table forecast_league.batches(run_key text primary key,created_at timestamptz not null default now(),payload jsonb not null,projections jsonb not null,madrid_run_key text not null,published_at timestamptz,request_id uuid unique,result jsonb);
create table public.forecast_round_public(team text primary key,run_key text not null, published_at timestamptz not null,payload jsonb not null,check(team<>'real-madrid'));
alter table forecast_league.teams enable row level security;
alter table forecast_league.roster enable row level security;
alter table forecast_league.batches enable row level security;
alter table public.forecast_round_public enable row level security;
revoke all on all tables in schema forecast_league from public,anon,authenticated,service_role;
revoke all on public.forecast_round_public from public,anon,authenticated,service_role;
grant select on public.forecast_round_public to anon,authenticated;
create policy published_round_read on public.forecast_round_public for select to anon,authenticated using(true);

